package com.bank.jvm;

import java.util.logging.*;

// Triggers an OOM variant and classifies it to show the triage process.
public class OomDiagnosticsDemo {
    private static final Logger log = Logger.getLogger(OomDiagnosticsDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OomClassifier classifier = new OomClassifier();
        String mode = args.length > 0 ? args[0] : "heap";

        try {
            switch (mode) {
                case "heap"   -> new ReportService().loadYearlyReport("CUR3001");
                case "thread" -> spawnUnboundedThreads();
                default       -> log.warning("Unknown mode: " + mode);
            }
        } catch (OutOfMemoryError oom) {
            classifier.classify(oom); // read the message, print cause + next step
        }
    }

    // Thread leak: creates threads with no bound -> "unable to create new native thread".
    private static void spawnUnboundedThreads() {
        java.util.List<Thread> leaked = new java.util.ArrayList<>();
        while (true) {
            Thread t = new Thread(() -> { try { Thread.sleep(600_000); } catch (InterruptedException ignored) {} });
            t.start();
            leaked.add(t); // keep references so they are not collected
        }
    }
}

