class ReportService {
    private static final Logger log = Logger.getLogger(ReportService.class.getName());
    // Anti-pattern: loads an entire year of transactions into one list at once.
    void loadYearlyReport(String accountId) {
        log.info("Loading full-year report for " + accountId + " (loads everything into memory)");
        java.util.List<byte[]> allTransactions = new java.util.ArrayList<>();
        while (true) {
            allTransactions.add(new byte[1024 * 1024]); // 1MB "transaction batch" each
        }
    }
}

