class OomClassifier {
    private static final Logger log = Logger.getLogger(OomClassifier.class.getName());

    // The core triage: branch on the error message to identify the exhausted region.
    void classify(OutOfMemoryError oom) {
        String msg = String.valueOf(oom.getMessage());
        log.severe("OutOfMemoryError caught: " + msg);
        if (msg.contains("Java heap space")) {
            log.severe("CAUSE: heap exhausted (leak OR loading too much at once).");
            log.severe("NEXT: analyze the auto heap dump in Eclipse MAT -> Dominator Tree.");
        } else if (msg.contains("Metaspace")) {
            log.severe("CAUSE: class-metadata exhausted (class-loader leak likely).");
            log.severe("NEXT: track loaded-class count; find retained class loaders; cap MaxMetaspaceSize.");
        } else if (msg.contains("unable to create new native thread")) {
            log.severe("CAUSE: OS refused a new thread (thread leak or ulimit).");
            log.severe("NEXT: use a bounded thread pool; check OS ulimit -u and -Xss.");
        } else if (msg.contains("GC overhead limit exceeded")) {
            log.severe("CAUSE: GC running constantly, freeing almost nothing (heap problem).");
            log.severe("NEXT: treat like heap space -> heap dump + leak analysis.");
        } else {
            log.severe("CAUSE: unrecognized OOM region. NEXT: inspect full message + heap dump.");
        }
    }
}
